"""Build dependency-free pages. Set SITE_URL when the custom domain is connected."""
import os,json,html
from pathlib import Path
ROOT=Path(__file__).parent
SITE=os.environ.get('SITE_URL','https://civnexus.github.io/bhogi').rstrip('/')
data=json.loads((ROOT/'content/book.json').read_text())
esc=html.escape
DESC='Autobiography of a Bhogi: Tridib Nandy’s unfolding story of Yogi and Bhogi, spiritual inheritance, youthful mischief, and a life drawn toward the world.'
def head(title,path='',prefix='',description=DESC):
 url=SITE+'/'+path
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'url':url,'description':description,'isPartOf':{'@type':'WebSite','name':data['title'],'alternateName':data['alternateTitle'],'url':SITE+'/'},'about':{'@type':'CreativeWork','name':data['title'],'alternateName':data['alternateTitle'],'author':{'@type':'Person','name':data['author']},'inLanguage':'en','creativeWorkStatus':'Work in progress'}}
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta name="theme-color" content="#062326"><link rel="canonical" href="{url}"><meta name="robots" content="index,follow"><meta property="og:type" content="website"><meta property="og:site_name" content="Autobiography of a Bhogi"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{SITE}/assets/social.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:alt" content="Autobiography of a Bhogi by Tridib Nandy — gold lettering beside an illustrated window opening onto a sunlit river"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(description)}"><meta name="twitter:image" content="{SITE}/assets/social.jpg"><meta name="twitter:image:alt" content="Autobiography of a Bhogi by Tridib Nandy"><link rel="icon" href="{prefix}favicon.ico" sizes="any"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="{prefix}assets/apple-touch-icon.png"><link rel="stylesheet" href="{prefix}assets/style.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>'''
def header(prefix=''):
 return f'''<a class="skip" href="#main">Skip to content</a><header class="wrap topbar"><a class="brand" href="{prefix}index.html" aria-label="Bhogi home">bhogi<span>.</span>life</a><nav aria-label="Main navigation"><a href="{prefix}index.html#story">The story</a><a href="{prefix}index.html#chapters">Chapters</a><a href="{prefix}index.html#about">About the book</a></nav></header>'''
def footer(prefix=''):
 return f'''<footer class="wrap"><span>© Tridib Nandy · Autobiography of a Bhogi</span><span>A life in the telling. <a href="{prefix}index.html#chapters">Open the book ↑</a></span></footer>'''
rows=''.join(f'''<a class="chapter-row" href="chapters/{c['slug']}.html"><span class="number">0{i+1}</span><div><h3>{c['title']}</h3><p>{c['subtitle']}</p></div><div><span class="status">Opening fragment</span><span class="arrow" aria-hidden="true">↗</span></div></a>''' for i,c in enumerate(data['chapters']))
index=head('Autobiography of a Bhogi — Tridib Nandy')+'''<body>'''+header()+f'''<main id="main"><section class="wrap hero" aria-labelledby="book-title"><div><p class="eyebrow">A life in the telling · Tridib Nandy</p><h1 id="book-title">Autobiography<br>of a <em>Bhogi</em></h1><p class="intro">Between the inward path and the world outside, a life finds its own balance.</p><p class="byline">The unfolding story of Tridib Nandy</p><div class="buttons"><a class="button" href="chapters/a-yogi-and-a-bhogi.html">Begin the story <span aria-hidden="true">↗</span></a><a class="textlink" href="#chapters">Explore the chapters</a></div></div><div><figure class="cover"><img src="assets/cover-860.webp" srcset="assets/cover-480.webp 480w, assets/cover-860.webp 860w" sizes="(max-width:760px) 330px, 430px" width="860" height="1290" fetchpriority="high" alt="Original gold and teal illustration: an open arched window, birds, and a river winding toward the rising sun"><figcaption class="cover-title">Autobiography<br>of a Bhogi<small>TRIDIB NANDY</small></figcaption></figure><p class="cover-caption">An open window. An unfinished story.</p></div></section><div class="wrap hero-note"><span>Spiritual roots. An earthly appetite.</span><span class="star" aria-hidden="true">✦</span><span>The first pages · A work in progress</span></div><section class="paper" id="story"><div class="wrap"><div class="split"><div><p class="eyebrow">01 / The premise</p><h2>Two impulses.<br>One life.</h2></div><div class="prose"><p>Tridib begins with a playful turn on <em>Autobiography of a Yogi</em>: what if this were the autobiography of a <em>Bhogi</em>—the indulgent man, as he puts it?</p><p>His ancestors, he says, were yogis. His own story brings another energy to that inheritance: curiosity, mischief, and an appetite for life. The invitation is to hold both together.</p></div></div><div class="duality"><div><h3>The Yogi</h3><p>The inward path. Spiritual inheritance. Contemplation.</p></div><div class="symbol" aria-hidden="true">∞</div><div><h3>The Bhogi</h3><p>The world’s invitation. Experience. Earthly delight.</p></div></div></div></section><section class="wrap section" id="chapters"><div class="section-head"><div><p class="eyebrow">02 / Inside the book</p><h2>A story, opening.</h2></div><p>Three brief opening fragments. The chapters will grow as the telling continues.</p></div><div class="chapter-list">{rows}</div></section><section class="quote-section"><div class="wrap"><p class="eyebrow">In his own words</p><blockquote>“In this life we have to be both<br>a <em>Yogi</em> and a <em>Bhogi</em>.”</blockquote><p class="quote-source">Tridib Nandy · On Yogi and Bhogi</p></div></section><section class="wrap section" id="about"><div class="split"><div><p class="eyebrow">03 / About the book</p><h2>A life, still<br>in the telling.</h2></div><div class="prose"><p><em>Autobiography of a Bhogi</em> is Tridib Nandy’s unfolding account of spiritual inheritance and earthly experience.</p><p>These first pages introduce its themes: the balance of Yogi and Bhogi, a mischievous childhood, and the pull of music, sports, birds, and the world beyond a classroom window.</p><p>The book begins here, with room for the memories and chapters still to come.</p></div></div></section><section class="closing wrap"><p class="eyebrow">Biography of Bhogi · An evolving book</p><h2>Every life has a window.<br>This one is opening.</h2><p>A few memories now. A fuller story, chapter by chapter.</p><a class="button" href="chapters/the-boy-at-the-window.html">Meet the boy at the window <span aria-hidden="true">↗</span></a></section></main>'''+footer()+'''</body></html>'''
(ROOT/'index.html').write_text(index)
for i,c in enumerate(data['chapters']):
 prev=data['chapters'][i-1] if i else None
 nxt=data['chapters'][i+1] if i+1<len(data['chapters']) else None
 nav=(f'<a href="{prev["slug"]}.html">← {prev["title"]}</a>' if prev else '<a href="../index.html#chapters">← Contents</a>')+(f'<a href="{nxt["slug"]}.html">{nxt["title"]} →</a>' if nxt else '<a href="../index.html#chapters">Back to contents →</a>')
 page=head(c['title']+' — Autobiography of a Bhogi','chapters/'+c['slug']+'.html','../',c['subtitle'])+'<body class="reader"><div class="progress" aria-hidden="true"></div>'+header('../')+f'''<main id="main" class="reader-main"><article><p class="eyebrow">Autobiography of a Bhogi · Fragment 0{i+1}</p><h1>{c['title']}</h1><p class="lead">{c['subtitle']}</p><div class="reader-tools"><span>Make yourself comfortable</span><button data-size="-2" aria-label="Decrease text size">A−</button><button data-size="2" aria-label="Increase text size">A+</button><button data-theme aria-pressed="false">Night reading</button></div><div class="body-copy">{''.join('<p>'+esc(p)+'</p>' for p in c['paragraphs'])}</div><p class="editor-note">Opening fragment · An editorial adaptation of Tridib Nandy’s recollections, prepared for this first website concept. This is not yet a completed autobiographical chapter.</p><nav class="chapter-nav" aria-label="Chapter navigation">{nav}</nav></article></main>'''+footer('../')+'<script src="../assets/reader.js" defer></script></body></html>'
 (ROOT/'chapters'/f'{c["slug"]}.html').write_text(page)
urls=[SITE+'/']+[SITE+'/chapters/'+c['slug']+'.html' for c in data['chapters']]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>\n')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+SITE+'/sitemap.xml\n')
(ROOT/'.nojekyll').touch()
(ROOT/'404.html').write_text(head('Page not found — Bhogi',prefix=SITE+'/')+'<body>'+header(SITE+'/')+ '<main id="main" class="wrap section"><p class="eyebrow">A page beyond the story</p><h1>This page has not been written.</h1><p><a href="'+SITE+'/">Return to the book →</a></p></main>'+footer()+'</body></html>')
print('Built home, 3 fragments, sitemap, robots and 404 for '+SITE)
